window.QUIZ_BANK['testng'] = (window.QUIZ_BANK['testng']||[]).concat([
{id:1981,topic:'testng',difficulty:'beginner',question:'Which annotation is used to initialize a WebDriver instance before each test method in a TestNG + Selenium setup?',options:['@BeforeSuite','@BeforeClass','@BeforeMethod','@BeforeTest'],answer:2,explanation:'@BeforeMethod runs before every individual @Test method, making it ideal for creating a fresh WebDriver instance per test to ensure isolation and avoid shared state across tests.'},
{id:1982,topic:'testng',difficulty:'intermediate',question:'What is the recommended way to store WebDriver instances when running TestNG tests in parallel to avoid thread-safety issues?',options:['A static WebDriver field','A ThreadLocal<WebDriver> variable','A singleton WebDriver factory','A synchronized WebDriver pool'],answer:1,explanation:'ThreadLocal<WebDriver> provides each thread its own WebDriver instance. In parallel execution, multiple threads run concurrently; a shared static field would cause race conditions, whereas ThreadLocal guarantees per-thread isolation.'},
{id:1983,topic:'testng',difficulty:'intermediate',question:'In a TestNG parallel Selenium framework, where should ThreadLocal<WebDriver> typically be declared and managed?',options:['Inside each @Test method','In a base test class with @BeforeMethod and @AfterMethod','In testng.xml as a parameter','In the Maven Surefire plugin configuration'],answer:1,explanation:'A base test class is the standard pattern: @BeforeMethod calls ThreadLocal.set(new ChromeDriver()) and @AfterMethod calls driver.quit() then ThreadLocal.remove(), ensuring clean lifecycle management for every thread.'},
{id:1984,topic:'testng',difficulty:'intermediate',question:'What does calling ThreadLocal.remove() in @AfterMethod prevent in a long-running Selenium test suite?',options:['Browser crashes','Memory leaks from retained driver references','Flaky test results','XML parsing errors'],answer:1,explanation:'Failing to call ThreadLocal.remove() after quitting the driver leaves a stale reference inside the thread-local map. In thread-pool environments this causes memory leaks because the thread is reused and the old value persists.'},
{id:1985,topic:'testng',difficulty:'beginner',question:'Which TestNG annotation should call driver.quit() to properly close the browser after each test method?',options:['@AfterSuite','@AfterClass','@AfterMethod','@AfterGroups'],answer:2,explanation:'@AfterMethod executes after every individual test method. Calling driver.quit() here ensures the browser is closed after each test, preventing resource exhaustion and ensuring subsequent tests start with a clean browser session.'},
{id:1986,topic:'testng',difficulty:'intermediate',question:'When integrating TestNG with Spring Boot tests, which annotation is placed on the test class to load the full Spring application context?',options:['@SpringBootTest','@ContextConfiguration','@RunWith(SpringRunner.class)','@EnableAutoConfiguration'],answer:0,explanation:'@SpringBootTest (from spring-boot-test) bootstraps the complete Spring application context for integration tests. It replaces the older @RunWith(SpringRunner.class) + @SpringBootTest combination when using newer Spring Boot versions with TestNG.'},
{id:1987,topic:'testng',difficulty:'intermediate',question:'Which Spring TestNG support class should a TestNG test class extend to enable Spring dependency injection in test methods?',options:['AbstractTestNGSpringContextTests','AbstractTransactionalTestNGSpringContextTests','SpringTestNGHelper','TestNGSpringRunner'],answer:0,explanation:'AbstractTestNGSpringContextTests is provided by spring-test and hooks into TestNG listeners to load and cache the Spring ApplicationContext, enabling @Autowired and @Value injection in TestNG-based Spring tests.'},
{id:1988,topic:'testng',difficulty:'advanced',question:'In a TestNG + Spring Boot test, which class provides both Spring context loading AND transactional rollback support per test method?',options:['AbstractTestNGSpringContextTests','AbstractTransactionalTestNGSpringContextTests','SpringBootTestNG','TransactionalTestSupport'],answer:1,explanation:'AbstractTransactionalTestNGSpringContextTests extends AbstractTestNGSpringContextTests and adds transaction management: each test method runs in a transaction that is rolled back by default, keeping the database clean between tests.'},
{id:1989,topic:'testng',difficulty:'intermediate',question:'How do you integrate Mockito with TestNG when you cannot use JUnit\'s @ExtendWith(MockitoExtension.class)?',options:['Call MockitoAnnotations.openMocks(this) in @BeforeMethod','Add @RunWith(MockitoJUnitRunner.class) to the class','Use @MockitoSettings on the class','Add mockito-testng dependency and @MockitoSettings'],answer:0,explanation:'Since TestNG does not use JUnit runners or extensions, the portable approach is to call MockitoAnnotations.openMocks(this) inside a @BeforeMethod. This initializes all @Mock, @Spy, and @InjectMocks annotations before each test runs.'},
{id:1990,topic:'testng',difficulty:'intermediate',question:'The mockito-testng library provides which listener that automates mock initialization for TestNG tests?',options:['MockitoTestNGListener','MockitoListener','MockAnnotationListener','MockitoSuiteListener'],answer:0,explanation:'The mockito-testng artifact (org.mockito:mockito-testng) provides MockitoTestNGListener. Adding @Listeners(MockitoTestNGListener.class) to a test class automatically opens and closes mocks, eliminating the need for manual MockitoAnnotations.openMocks() calls.'},
{id:1991,topic:'testng',difficulty:'beginner',question:'What is the purpose of SoftAssert in TestNG?',options:['To skip failed assertions','To allow multiple assertions to run even after one fails, reporting all failures at the end','To assert asynchronous conditions','To compare XML files'],answer:1,explanation:'SoftAssert collects all assertion failures without throwing an exception immediately. After all assertions are executed, calling assertAll() throws a single exception listing every failure, allowing you to see the full picture of a test\'s state.'},
{id:1992,topic:'testng',difficulty:'intermediate',question:'What happens if you forget to call softAssert.assertAll() at the end of a TestNG test using SoftAssert?',options:['The test fails immediately','All soft assertion failures are silently ignored and the test passes','A NullPointerException is thrown','The test is skipped'],answer:1,explanation:'Without assertAll(), SoftAssert never reports its collected failures. The test method completes without any exception being thrown, so TestNG marks it as passed even if multiple soft assertions failed — a dangerous silent omission.'},
{id:1993,topic:'testng',difficulty:'intermediate',question:'In TestNG, should you use a single SoftAssert instance across multiple test methods in a class?',options:['Yes, to accumulate failures across tests','No, each test method must create its own SoftAssert instance','Yes, if declared as a static field','Only when using parallel execution'],answer:1,explanation:'Reusing a SoftAssert across tests mixes failure records from different methods, making it impossible to attribute failures correctly. Each @Test method must instantiate its own SoftAssert to maintain clean, isolated assertion contexts.'},
{id:1994,topic:'testng',difficulty:'advanced',question:'Which SoftAssert method verifies that two objects are equal AND continues execution even if they differ?',options:['assertEquals (throws immediately)','softAssert.assertEquals','softAssert.verifyEquals','softAssert.assertEqualsNoOrder'],answer:1,explanation:'SoftAssert.assertEquals(actual, expected, message) records a failure internally if values differ but does not throw, allowing subsequent lines to execute. The hard Assert.assertEquals would immediately throw AssertionError and halt the test method.'},
{id:1995,topic:'testng',difficulty:'intermediate',question:'When TestNG runs tests in parallel at the "methods" level, what is the primary thread-safety concern?',options:['Slow test execution','Shared mutable state in test class fields being accessed by multiple threads simultaneously','TestNG XML parsing failures','Incorrect group filtering'],answer:1,explanation:'At parallel="methods", TestNG runs multiple @Test methods concurrently, possibly on the same class instance. Any mutable instance field (like a shared WebDriver or counter) becomes a race condition. The fix is ThreadLocal or per-method instantiation.'},
{id:1996,topic:'testng',difficulty:'intermediate',question:'Which parallel mode in TestNG creates a separate thread for each test class, running all methods of a class sequentially within that thread?',options:['parallel="methods"','parallel="classes"','parallel="tests"','parallel="instances"'],answer:1,explanation:'parallel="classes" assigns each test class its own thread. Methods within a class run sequentially on that thread, which is safer for classes that share state but still achieves parallelism across multiple classes in the suite.'},
{id:1997,topic:'testng',difficulty:'advanced',question:'In testng.xml, what attribute controls the maximum number of threads TestNG uses during parallel execution?',options:['maxThreads','thread-count','parallelThreads','concurrency'],answer:1,explanation:'The thread-count attribute on the <suite> tag sets the thread pool size. For example, <suite thread-count="5" parallel="methods"> allows up to 5 test methods to run concurrently. Exceeding available CPU cores offers diminishing returns.'},
{id:1998,topic:'testng',difficulty:'advanced',question:'Which TestNG parallel mode is best suited for running the same tests against multiple browser/environment configurations simultaneously?',options:['parallel="methods"','parallel="classes"','parallel="tests"','parallel="instances"'],answer:2,explanation:'parallel="tests" runs each <test> block in testng.xml in its own thread. By defining multiple <test> blocks with different parameters (e.g., browser=chrome, browser=firefox), you can execute cross-browser tests concurrently.'},
{id:1999,topic:'testng',difficulty:'intermediate',question:'What is TestNG configuration inheritance in the context of class hierarchies?',options:['Subclasses override parent @Test methods','Subclasses inherit @Before* and @After* methods from parent classes and they are invoked automatically','TestNG copies XML config to child suites','Configuration files cascade from parent to child directories'],answer:1,explanation:'When a test class extends a base class, TestNG automatically discovers and executes @BeforeSuite, @BeforeClass, @BeforeMethod (and their @After* counterparts) defined in parent classes, enabling shared setup logic through inheritance without duplication.'},
{id:2000,topic:'testng',difficulty:'intermediate',question:'If both a parent class and a child class define @BeforeMethod, in what order are they executed?',options:['Child then parent','Parent then child','Alphabetical order','Undefined order'],answer:1,explanation:'TestNG respects the class hierarchy: parent class @BeforeMethod runs first, then the child class @BeforeMethod. Correspondingly, @AfterMethod runs in reverse — child first, then parent — mirroring a constructor/destructor chain.'},
{id:2001,topic:'testng',difficulty:'advanced',question:'How can you prevent a parent class @BeforeClass from being inherited and run in a TestNG subclass?',options:['Mark it as private','Use alwaysRun=false','Override it in the subclass with an empty method and no annotation','Add @Ignore to the parent method'],answer:2,explanation:'Overriding the parent\'s @BeforeClass with a plain method (no annotation) in the subclass prevents TestNG from calling the parent\'s annotated version via super-class dispatch, effectively suppressing the inherited configuration method.'},
{id:2002,topic:'testng',difficulty:'intermediate',question:'Which @Test attribute enforces that a specific test method runs only after another named method has succeeded?',options:['priority','dependsOnMethods','dependsOnGroups','runAfter'],answer:1,explanation:'dependsOnMethods={"methodName"} declares a hard dependency: if the named method fails or is skipped, the dependent test is automatically skipped. This enforces ordered execution where later tests depend on earlier ones passing.'},
{id:2003,topic:'testng',difficulty:'intermediate',question:'What is the difference between dependsOnMethods and priority in TestNG test ordering?',options:['No difference','priority sets execution order but does not skip on failure; dependsOnMethods creates a hard dependency that skips dependent tests on failure','priority skips tests; dependsOnMethods only orders them','They cannot be used together'],answer:1,explanation:'priority (lower number = earlier) controls order without creating dependencies — a lower-priority test still runs even if a higher-priority one failed. dependsOnMethods creates a semantic dependency: failure or skip of the dependency causes dependent tests to be skipped.'},
{id:2004,topic:'testng',difficulty:'beginner',question:'By default, if TestNG test methods have no priority specified, in what order do they run?',options:['Alphabetical order','Declaration order in source code','Random order','Reverse alphabetical order'],answer:0,explanation:'When no priority is assigned, TestNG sorts test methods alphabetically by method name. This is a defined default behavior, though it is best practice to use explicit priorities or dependencies when order matters rather than relying on alphabetic ordering.'},
{id:2005,topic:'testng',difficulty:'intermediate',question:'Which Maven plugin is used to execute TestNG tests during a Maven build?',options:['maven-testng-plugin','maven-surefire-plugin','maven-failsafe-plugin','maven-test-plugin'],answer:1,explanation:'The maven-surefire-plugin (version 2.20+) automatically detects TestNG on the classpath and uses it as the test provider. No special configuration is required beyond having testng in the dependencies; Surefire handles the integration transparently.'},
{id:2006,topic:'testng',difficulty:'intermediate',question:'How do you specify a custom testng.xml suite file in the Maven Surefire plugin configuration?',options:['<suiteFile>testng.xml</suiteFile>','<suiteXmlFiles><suiteXmlFile>testng.xml</suiteXmlFile></suiteXmlFiles>','<testng><xmlFile>testng.xml</xmlFile></testng>','<configuration><file>testng.xml</file></configuration>'],answer:1,explanation:'Inside the maven-surefire-plugin <configuration> block, the <suiteXmlFiles> element accepts one or more <suiteXmlFile> paths. Surefire passes these to TestNG\'s runtime, overriding its default class-scanning behavior with the defined suite structure.'},
{id:2007,topic:'testng',difficulty:'intermediate',question:'Which Maven Surefire plugin configuration element enables parallel test execution at the "methods" level?',options:['<parallel>methods</parallel>','<parallelExecution>methods</parallelExecution>','<forkMode>parallel</forkMode>','<concurrentTests>true</concurrentTests>'],answer:0,explanation:'The <parallel>methods</parallel> element within maven-surefire-plugin <configuration> instructs Surefire to pass the parallel mode to TestNG. Combining it with <threadCount>N</threadCount> sets the thread pool size for concurrent method execution.'},
{id:2008,topic:'testng',difficulty:'advanced',question:'What is the difference between maven-surefire-plugin and maven-failsafe-plugin for TestNG?',options:['No difference','Surefire runs unit tests (test phase) and fails the build immediately; Failsafe runs integration tests (integration-test phase) and defers build failure to the verify phase','Failsafe is for TestNG; Surefire is for JUnit only','Surefire supports parallel; Failsafe does not'],answer:1,explanation:'Surefire binds to the test phase and fails the build if tests fail. Failsafe binds to integration-test and verify phases, allowing post-integration cleanup (e.g., stopping a server) to run even when tests fail before marking the build as failed.'},
{id:2009,topic:'testng',difficulty:'intermediate',question:'Which Gradle plugin is used to run TestNG tests in a Gradle project?',options:['testng-gradle','gradle-testng-plugin','The built-in Gradle test task with useTestNG()','gradle-testng-runner'],answer:2,explanation:'Gradle\'s built-in Test task supports TestNG natively. Calling useTestNG() inside the test task configuration switches the test framework from the default JUnit to TestNG. You can also pass options like suiteXmlFiles and parallel settings.'},
{id:2010,topic:'testng',difficulty:'intermediate',question:'How do you specify a testng.xml file in a Gradle build script?',options:['test { testngXml = "testng.xml" }','test { useTestNG { suiteXmlFiles = ["testng.xml"] } }','testng { xmlFile "testng.xml" }','test { include "testng.xml" }'],answer:1,explanation:'Inside the Gradle test task, useTestNG() accepts a closure. Setting suiteXmlFiles = ["src/test/resources/testng.xml"] tells Gradle to use that XML suite definition, mirroring the Maven Surefire <suiteXmlFiles> configuration.'},
{id:2011,topic:'testng',difficulty:'beginner',question:'How do you run a TestNG suite from the command line using the TestNG jar directly?',options:['java -jar testng.jar testng.xml','java -cp testng.jar org.testng.TestNG testng.xml','testng run testng.xml','mvn testng:run'],answer:1,explanation:'TestNG\'s main class is org.testng.TestNG. Running java -cp <classpath> org.testng.TestNG testng.xml with the proper classpath (including testng.jar and test classes) executes the suite defined in testng.xml from the command line.'},
{id:2012,topic:'testng',difficulty:'intermediate',question:'Which command-line option for org.testng.TestNG runs a single specific test class without a testng.xml file?',options:['--class com.example.MyTest','--testclass com.example.MyTest','-testclass com.example.MyTest','-class com.example.MyTest'],answer:2,explanation:'The -testclass flag (note: single dash in TestNG CLI convention) accepts a fully qualified class name and runs all @Test methods in that class, bypassing the need for a testng.xml suite file for quick ad-hoc test execution.'},
{id:2013,topic:'testng',difficulty:'intermediate',question:'Which command-line option for TestNG specifies which groups to run?',options:['-groups','--groups','-group','-includeGroups'],answer:0,explanation:'The -groups option accepts a comma-separated list of group names (e.g., -groups "smoke,regression"). TestNG\'s main class uses this to filter which tests to execute, equivalent to defining <groups><run><include name="smoke"/></run></groups> in testng.xml.'},
{id:2014,topic:'testng',difficulty:'advanced',question:'In testng.xml, what XPath-like syntax is used to include test classes from a specific package including all sub-packages?',options:['<package name="com.example.*"/>','<package name="com.example" recursive="true"/>','<package name="com.example"/>','<classes path="com/example"/>'],answer:2,explanation:'The <package name="com.example"/> element in testng.xml scans the named package and all its sub-packages for test classes automatically. This is simpler than listing every class individually and naturally picks up new classes as they are added.'},
{id:2015,topic:'testng',difficulty:'intermediate',question:'How do you include only test methods whose names match a regular expression in testng.xml?',options:['<include pattern="test.*"/>','<methods><include name="test.*"/></methods>','<filter regex="test.*"/>','<run regex="test.*"/>'],answer:1,explanation:'Inside a <class> element, <methods><include name="test.*"/></methods> uses the provided string as a regular expression to match method names. Only methods matching the pattern are included; others are excluded automatically.'},
{id:2016,topic:'testng',difficulty:'intermediate',question:'What does the <exclude name=".*Integration.*"/> element inside <methods> accomplish in testng.xml?',options:['Excludes test classes with "Integration" in their name','Excludes test methods whose names contain "Integration"','Excludes the entire Integration test group','Excludes packages named Integration'],answer:1,explanation:'When placed inside <methods>, the <exclude name=".*Integration.*"/> regex filter prevents any method whose name matches the pattern from being executed. This is useful for temporarily skipping slow integration-level methods during development.'},
{id:2017,topic:'testng',difficulty:'beginner',question:'Where does TestNG generate its default HTML and XML test results reports?',options:['target/surefire-reports','test-output directory in the project root','build/reports/tests','src/test/results'],answer:1,explanation:'By default, TestNG writes its reports to a folder called test-output in the working directory. This folder contains index.html (summary), emailable-report.html (single-file report), testng-results.xml, and detailed per-suite reports.'},
{id:2018,topic:'testng',difficulty:'intermediate',question:'Which TestNG XML report file is commonly consumed by CI systems like Jenkins to display test results?',options:['testng-results.xml','index.html','emailable-report.html','surefire-report.xml'],answer:0,explanation:'testng-results.xml follows the surefire XML schema that Jenkins\' JUnit test result plugin understands. CI systems parse this file to display pass/fail counts, test durations, and failure messages in the build dashboard.'},
{id:2019,topic:'testng',difficulty:'intermediate',question:'Which Allure annotation is used to set the display name of a TestNG test in an Allure report?',options:['@AllureName','@DisplayName','@Title','@Feature'],answer:2,explanation:'Allure\'s @Title("Human Readable Name") annotation (from io.qameta.allure.Description or io.qameta.allure.Title) sets a readable test title in the Allure report, replacing the method name with a descriptive string for better readability.'},
{id:2020,topic:'testng',difficulty:'intermediate',question:'Which Allure annotation groups related tests under a feature in the Allure report hierarchy?',options:['@Suite','@Feature','@Story','@Epic'],answer:1,explanation:'@Feature("Feature Name") categorizes tests under a feature in the Allure report\'s tree view. Combined with @Epic (top-level) and @Story (sub-level), it creates a three-level BDD-style hierarchy: Epic > Feature > Story.'},
{id:2021,topic:'testng',difficulty:'intermediate',question:'How do you integrate Allure with TestNG in a Maven project?',options:['Add allure-testng dependency and configure the allure-maven plugin','Add @AllureListener to each test class','Extend AllureTestNGListener in every test class','Set allure=true in testng.xml'],answer:0,explanation:'Adding the allure-testng dependency (io.qameta.allure:allure-testng) registers AllureTestNGListener automatically via Java ServiceLoader. The allure-maven plugin then generates the HTML report from the raw JSON results produced by the listener.'},
{id:2022,topic:'testng',difficulty:'advanced',question:'Which Allure method attaches a screenshot as a byte array to the current test step?',options:['Allure.addAttachment()','Allure.attach()','Allure.screenshot()','Allure.step()'],answer:1,explanation:'Allure.attach(name, mediaType, content) attaches arbitrary content to the current test. For screenshots, you pass the PNG byte array with media type "image/png". This makes screenshot on failure reports directly visible in the Allure HTML report.'},
{id:2023,topic:'testng',difficulty:'intermediate',question:'Which class is the main entry point for creating an ExtentReports report in the AventStack ExtentReports library?',options:['ExtentTest','ExtentHtmlReporter','ExtentReports','HtmlReporter'],answer:2,explanation:'ExtentReports is the central manager object. You attach one or more reporters (e.g., ExtentSparkReporter) to it, create ExtentTest objects for each test, and call flush() at the end to write the complete report to disk.'},
{id:2024,topic:'testng',difficulty:'intermediate',question:'Which TestNG listener interface is typically implemented to integrate ExtentReports with a TestNG suite?',options:['ITestListener','ISuiteListener','IReporter','IInvokedMethodListener'],answer:0,explanation:'Implementing ITestListener gives callbacks for onTestStart, onTestSuccess, onTestFailure, and onTestSkipped. These are used to create ExtentTest nodes and log pass/fail status, making ITestListener the standard integration point for ExtentReports.'},
{id:2025,topic:'testng',difficulty:'advanced',question:'In ExtentReports + TestNG integration, why should ExtentTest objects be stored in a ThreadLocal variable?',options:['To improve report rendering speed','To prevent one thread from overwriting another thread\'s test node during parallel test execution','To enable automatic screenshot capture','To allow report generation without calling flush()'],answer:1,explanation:'During parallel execution multiple threads call onTestStart concurrently. A ThreadLocal<ExtentTest> ensures each thread writes to its own ExtentTest node. Without it, concurrent writes to a shared field produce corrupted or mixed test log entries.'},
{id:2026,topic:'testng',difficulty:'intermediate',question:'How do you add Log4j 2 logging to a TestNG test class?',options:['Extend TestNGLogger','Add @Log4j2 (Lombok) or create a Logger with LogManager.getLogger(getClass())','Configure log4j in testng.xml','Use TestNG\'s built-in Reporter.log() method'],answer:1,explanation:'Standard Log4j 2 usage applies: declare a static final Logger logger = LogManager.getLogger(MyTest.class) or use Lombok\'s @Log4j2. The logger is configured via log4j2.xml on the classpath and works transparently alongside TestNG\'s own reporting.'},
{id:2027,topic:'testng',difficulty:'intermediate',question:'What is the advantage of using SLF4J with a Log4j 2 binding in TestNG tests versus using Log4j 2 directly?',options:['SLF4J is faster','SLF4J provides a facade that decouples test code from the logging implementation, making it easy to switch backends without changing test source code','SLF4J supports parallel logging; Log4j 2 does not','SLF4J integrates natively with TestNG; Log4j 2 does not'],answer:1,explanation:'SLF4J is a logging facade (API). By coding against SLF4J, test classes are not coupled to Log4j 2 specifically. Swapping the binding jar (e.g., to Logback) requires no source changes, which is valuable in multi-module projects with varying logging requirements.'},
{id:2028,topic:'testng',difficulty:'advanced',question:'Which TestNG listener interface provides callbacks before and after each method invocation, including configuration methods like @BeforeMethod?',options:['ITestListener','IInvokedMethodListener','ISuiteListener','IMethodInterceptor'],answer:1,explanation:'IInvokedMethodListener fires beforeInvocation() and afterInvocation() for every method TestNG invokes — both @Test methods AND configuration methods (@BeforeMethod, @AfterMethod, etc.). This makes it more comprehensive than ITestListener, which only covers test methods.'},
{id:2029,topic:'testng',difficulty:'advanced',question:'In IInvokedMethodListener, how can you determine whether the invoked method is a test method vs. a configuration method?',options:['method.isTest() returns true for test methods','invokedMethod.isTestMethod() returns true for test methods','Check the annotation type on the method object','Use instanceof to check the ITestNGMethod type'],answer:1,explanation:'The IInvokedMethod parameter exposes isTestMethod() (returns true for @Test methods) and isConfigurationMethod() (returns true for @Before*/@After* methods). This allows you to apply different logic for setup/teardown vs. actual test invocations.'},
{id:2030,topic:'testng',difficulty:'advanced',question:'What is the purpose of the IAlterSuiteListener interface in TestNG?',options:['To modify test results after execution','To programmatically modify the XmlSuite object before tests run, changing groups, parameters, or parallel settings at runtime','To alter the HTML report output','To add extra suite files dynamically'],answer:1,explanation:'IAlterSuiteListener.alter(List<XmlSuite>) is called after testng.xml is parsed but before execution begins. It allows runtime modification of suite configuration — for example, injecting environment-specific parameters, changing parallel mode, or adding/removing test groups programmatically.'},
{id:2031,topic:'testng',difficulty:'intermediate',question:'Which @Test attribute marks a test method as belonging to one or more named groups?',options:['category','group','groups','tags'],answer:2,explanation:'The groups attribute accepts a String array: @Test(groups={"smoke","regression"}). Groups are used in testng.xml <groups> sections to include or exclude sets of tests, enabling selective execution without modifying source code.'},
{id:2032,topic:'testng',difficulty:'intermediate',question:'What does the @Test(enabled=false) attribute do?',options:['Marks the test as skipped in the report','Prevents TestNG from executing the method; it is not even compiled out','The test is excluded from the run and reported as skipped','Both A and C — it prevents execution and reports as skipped'],answer:3,explanation:'Setting enabled=false tells TestNG to skip the method entirely. The test appears in the report with SKIP status (not as ignored or missing). It is the simplest way to temporarily disable a test without deleting or commenting out code.'},
{id:2033,topic:'testng',difficulty:'intermediate',question:'Which @Test attribute sets a maximum execution time (in milliseconds) after which the test is marked as failed?',options:['timeout','maxTime','timeLimit','invocationTimeout'],answer:0,explanation:'@Test(timeoutInMilliseconds=...) — more commonly written as @Test(timeOut=5000) — causes TestNG to run the test on a separate thread and interrupt it if it does not complete within the specified number of milliseconds, marking it as failed.'},
{id:2034,topic:'testng',difficulty:'intermediate',question:'What does @Test(invocationCount=5) do?',options:['Runs the test on 5 parallel threads','Runs the test method 5 times sequentially (or in parallel with threadPoolSize)','Retries the test up to 5 times on failure','Runs the test for 5 seconds'],answer:1,explanation:'invocationCount=N causes TestNG to invoke the test method N times. Combined with threadPoolSize=T, up to T invocations run concurrently. This is useful for load/stress testing a method or checking for intermittent failures by repeating the test.'},
{id:2035,topic:'testng',difficulty:'advanced',question:'Which @Test attribute, when set to true, causes TestNG to run this test always, even if it depends on a failed group or method?',options:['forceRun','alwaysRun','ignoreFailure','runOnFailure'],answer:1,explanation:'@Test(alwaysRun=true) ensures the method runs regardless of the outcome of methods or groups it depends on. It is commonly used for cleanup tests that must execute even when earlier steps fail, similar to @AfterMethod behavior.'},
{id:2036,topic:'testng',difficulty:'intermediate',question:'What does @Test(singleThreaded=true) applied to a test class mean?',options:['All methods run on the main thread','All methods of the class run sequentially in a single thread, even during parallel suite execution','Only one instance of the class is created','The class cannot use DataProvider'],answer:1,explanation:'When parallel execution is enabled at the suite level, @Test(singleThreaded=true) on a class overrides that: all methods of that class are run sequentially in one thread. This is useful for stateful classes where method order and isolation matter.'},
{id:2037,topic:'testng',difficulty:'intermediate',question:'Which pattern is used in TestNG for cross-browser testing where the browser name is passed as a parameter from testng.xml?',options:['@Factory with browser field','@Parameters with browser parameter in testng.xml <test> blocks','@DataProvider returning browser names','Both B and C are valid patterns'],answer:3,explanation:'Both are valid: @Parameters({"browser"}) reads the browser value from testng.xml <parameter name="browser" value="chrome"/>, running the same class once per <test> block. @DataProvider(name="browsers") provides [["chrome"],["firefox"]] rows, running each @Test method for each browser.'},
{id:2038,topic:'testng',difficulty:'intermediate',question:'In testng.xml, how do you define a parameter that is available to all tests in the suite?',options:['Add <parameter> inside <suite>','Add <parameter> inside <test>','Add <parameter> inside <class>','Parameters can only be defined at the <test> level'],answer:0,explanation:'Parameters defined at the <suite> level are inherited by all <test> blocks. Parameters at the <test> level apply only to that block. A <test>-level parameter with the same name overrides the suite-level value, providing a cascading override mechanism.'},
{id:2039,topic:'testng',difficulty:'advanced',question:'How can you implement environment-specific configuration in TestNG so that dev, staging, and prod configs are loaded automatically?',options:['Use Maven profiles to set a system property, read it in @BeforeSuite with System.getProperty(), and load the corresponding properties file','Hard-code environment values in testng.xml','Use TestNG groups as environment names','Set ENV variable in @BeforeMethod'],answer:0,explanation:'Maven profiles set -Denv=staging which @BeforeSuite reads via System.getProperty("env","dev"). The appropriate properties file (config-staging.properties) is loaded, making base URL, credentials, and other settings environment-aware without modifying test code.'},
{id:2040,topic:'testng',difficulty:'intermediate',question:'Which TestNG mechanism allows providing test data from an external source such as a database or CSV file?',options:['@Parameters','@DataProvider','@Factory','@ExternalData'],answer:1,explanation:'@DataProvider methods return Object[][] (or Iterator<Object[]>). The data can be loaded from any source: CSV readers, JDBC ResultSets, Excel files via Apache POI, or JSON parsers. The @Test method receives each row as method arguments on successive invocations.'},
{id:2041,topic:'testng',difficulty:'intermediate',question:'How do you pass JSON test data to a TestNG @DataProvider?',options:['TestNG reads JSON natively from testng.xml','Parse the JSON file manually (e.g., with Jackson/Gson) inside the @DataProvider method and return Object[][]','Use @JsonFile annotation on the @Test method','Configure json-provider in the Maven Surefire plugin'],answer:1,explanation:'TestNG has no built-in JSON support. You implement the @DataProvider method to open the JSON file, parse it with Jackson ObjectMapper or Gson, map each object to a test parameter set, and return the resulting Object[][] to TestNG.'},
{id:2042,topic:'testng',difficulty:'advanced',question:'How would you load YAML test data in a TestNG @DataProvider?',options:['Use TestNG\'s built-in YAML support','Use SnakeYAML (or similar) to parse the YAML file inside the @DataProvider, converting each entry to an Object[] row','Convert YAML to XML first, then use @Parameters','YAML is not supported by TestNG DataProviders'],answer:1,explanation:'SnakeYAML\'s Yaml.loadAll() or similar APIs read YAML documents into Java objects. The @DataProvider then wraps these into Object[][] rows. This pattern treats YAML as a human-friendly alternative to CSV for data-driven tests.'},
{id:2043,topic:'testng',difficulty:'intermediate',question:'Which Jenkins plugin is typically used to display TestNG test results in the Jenkins build dashboard?',options:['TestNG Results Plugin','JUnit Plugin (reads testng-results.xml)','TestNG Jenkins Integrator','Both A and B are valid'],answer:3,explanation:'Both the dedicated TestNG Results Plugin and the JUnit plugin can parse TestNG output. testng-results.xml conforms to the surefire XML schema that the JUnit plugin understands. The TestNG Results Plugin provides additional TestNG-specific trend charts and details.'},
{id:2044,topic:'testng',difficulty:'intermediate',question:'In a Jenkins declarative pipeline, how do you archive TestNG results?',options:['post { always { junit "test-output/testng-results.xml" } }','testng results: "test-output/testng-results.xml"','archiveTests "testng-results.xml"','post { always { testngResults "**/testng-results.xml" } }'],answer:0,explanation:'The JUnit step (junit) reads the surefire-compatible XML output produced by TestNG. Placing it in post { always { ... } } ensures results are published whether the build passes or fails, giving visibility into failures that caused the build to break.'},
{id:2045,topic:'testng',difficulty:'intermediate',question:'Which CI best practice prevents TestNG parallel test failures from being hidden when using Maven in a Jenkins pipeline?',options:['Use -DfailIfNoTests=false','Use -Dsurefire.failIfNoSpecifiedTests=false','Use the maven-failsafe-plugin with verify goal and check its exit code','Run tests sequentially in CI'],answer:2,explanation:'The failsafe plugin separates test execution from failure reporting: the integration-test phase runs tests even if some fail, and the verify phase then fails the build. This ensures post-integration cleanup (server shutdown, reports) always runs before the build is marked failed.'},
{id:2046,topic:'testng',difficulty:'beginner',question:'What is a TestNG best practice regarding test method independence?',options:['Tests should share state through static variables for efficiency','Each test should be independent and not rely on the state left by another test','Tests should always run in alphabetical order','All tests should belong to the same group'],answer:1,explanation:'Independent tests can run in any order, be re-run in isolation, and run in parallel safely. Tests that depend on shared mutable state are brittle, order-dependent, and fail unpredictably. This is one of the foundational principles of reliable automated testing.'},
{id:2047,topic:'testng',difficulty:'intermediate',question:'Which is considered a TestNG anti-pattern when using @DataProvider?',options:['Loading data from external files','Returning Iterator<Object[]>','Hardcoding test data directly in production code loaded by the DataProvider','Using parallel=true on a DataProvider'],answer:2,explanation:'Coupling test data to production code (e.g., reading from src/main) breaks separation of concerns. Test data should live in test resources. Hardcoding in production classes also risks accidentally shipping test-specific logic to deployable artifacts.'},
{id:2048,topic:'testng',difficulty:'advanced',question:'What is the anti-pattern of using Thread.sleep() in TestNG + Selenium tests, and what should be used instead?',options:['Thread.sleep() is fine; there is no anti-pattern','Thread.sleep() creates fixed, brittle waits. Use WebDriverWait with ExpectedConditions for dynamic, condition-based waits','Thread.sleep() should be replaced with @Test(timeOut=...)','Use SoftAssert instead of Thread.sleep()'],answer:1,explanation:'Thread.sleep() adds unconditional delays that make tests slow and still flaky if conditions take longer than expected. WebDriverWait polls until a condition is met or a timeout expires, making tests faster when conditions resolve early and more robust when they take longer.'},
{id:2049,topic:'testng',difficulty:'intermediate',question:'How does TestNG compare to JUnit 5 regarding parallel execution configuration?',options:['JUnit 5 configures parallel execution in junit-platform.properties; TestNG configures it in testng.xml','Both use the same configuration file','JUnit 5 does not support parallel execution','TestNG does not support parallel execution'],answer:0,explanation:'TestNG uses testng.xml attributes (parallel, thread-count) and Java annotations to configure parallelism. JUnit 5 uses junit-platform.properties (junit.jupiter.execution.parallel.enabled=true, etc.). Both support parallel execution but through entirely different configuration mechanisms.'},
{id:2050,topic:'testng',difficulty:'intermediate',question:'How does TestNG\'s @DataProvider differ from JUnit 5\'s @MethodSource?',options:['No difference','@DataProvider returns Object[][] or Iterator<Object[]> from a method in the same or external class; @MethodSource references a static stream-producing method','@MethodSource supports external classes; @DataProvider does not','@DataProvider is type-safe; @MethodSource is not'],answer:1,explanation:'TestNG @DataProvider methods return Object[][] (or Iterator). JUnit 5 @MethodSource references a static method returning Stream<Arguments>. Both enable parameterized tests but with different APIs. @DataProvider can also be in a separate class using dataProviderClass attribute.'},
{id:2051,topic:'testng',difficulty:'intermediate',question:'Which JUnit 5 annotation is the closest equivalent to TestNG\'s @BeforeMethod?',options:['@BeforeEach','@BeforeAll','@Before','@Setup'],answer:0,explanation:'JUnit 5\'s @BeforeEach runs before every test method, exactly like TestNG\'s @BeforeMethod. Similarly, @AfterEach ≈ @AfterMethod, @BeforeAll ≈ @BeforeClass (both require static by default in JUnit 5), and @AfterAll ≈ @AfterClass.'},
{id:2052,topic:'testng',difficulty:'advanced',question:'Which feature does TestNG have that JUnit 5 lacks natively for XML-based suite composition?',options:['Parameterized tests','testng.xml suite files that define test class/method inclusion, groups, parameters, and parallel settings in a single XML configuration','Nested test classes','Dynamic tests'],answer:1,explanation:'TestNG\'s testng.xml is a powerful suite orchestrator with no direct JUnit 5 equivalent. JUnit 5 relies on build tool configuration (Maven/Gradle) or platform launcher API for similar orchestration. testng.xml offers fine-grained group, parameter, and listener control in one file.'},
{id:2053,topic:'testng',difficulty:'intermediate',question:'How do you assert that a List contains specific elements using TestNG\'s Assert class?',options:['Assert.assertContains(list, element)','Assert.assertTrue(list.contains(element))','Assert.assertListContains(list, elements)','Assert.assertIn(element, list)'],answer:1,explanation:'TestNG\'s Assert does not have a dedicated assertContains for lists. The standard approach is Assert.assertTrue(list.contains(element), "message"). For full collection equality, Assert.assertEquals(actualList, expectedList) compares content and order.'},
{id:2054,topic:'testng',difficulty:'intermediate',question:'Which TestNG Assert method compares two collections without regard to element order?',options:['Assert.assertEquals(set1, set2)','Assert.assertEqualsNoOrder(actual, expected)','Assert.assertCollectionEquals(actual, expected)','Assert.assertContainsAll(actual, expected)'],answer:1,explanation:'Assert.assertEqualsNoOrder(Object[] actual, Object[] expected) verifies that both arrays contain the same elements regardless of order. It is useful for assertions on results from unordered queries where element order is non-deterministic but content matters.'},
{id:2055,topic:'testng',difficulty:'advanced',question:'How do you assert that two lists contain the same elements (any order) when using TestNG\'s Assert?',options:['Assert.assertEqualsNoOrder(list1.toArray(), list2.toArray())','Assert.assertListEquals(list1, list2)','Assert.assertSameElements(list1, list2)','Assert.assertCollectionEqualsNoOrder(list1, list2)'],answer:0,explanation:'Since assertEqualsNoOrder accepts Object arrays, converting lists with toArray() bridges the gap. Alternatively, convert both lists to HashSets and use Assert.assertEquals(new HashSet<>(list1), new HashSet<>(list2)) to compare contents ignoring order.'},
{id:2056,topic:'testng',difficulty:'intermediate',question:'How do you integrate REST Assured with TestNG for API testing?',options:['REST Assured requires JUnit; it does not work with TestNG','Add rest-assured dependency and use RestAssured.given()...then().statusCode() inside @Test methods','Use @RestTest annotation from REST Assured','Extend RestAssuredTestNG base class'],answer:1,explanation:'REST Assured is framework-agnostic. Adding the rest-assured dependency is sufficient; its fluent API (given/when/then) works inside any @Test method. TestNG handles lifecycle and reporting while REST Assured handles HTTP request/response construction and assertion.'},
{id:2057,topic:'testng',difficulty:'intermediate',question:'Which REST Assured feature integrates well with TestNG\'s soft assertions?',options:['ResponseSpecBuilder','REST Assured does not support soft assertions','Using SoftAssert to validate individual fields extracted from the response with jsonPath()','REST Assured has its own SoftAssert equivalent'],answer:2,explanation:'After extracting values from a REST Assured response (e.g., response.jsonPath().getString("name")), those values can be passed to TestNG\'s SoftAssert methods. This enables verifying multiple response fields in a single test while collecting all failures before assertAll().'},
{id:2058,topic:'testng',difficulty:'advanced',question:'How do you implement a request specification in REST Assured that is reused across multiple TestNG test methods?',options:['Declare a static RequestSpecification in a base class and initialize it in @BeforeClass','Each test method must define its own request spec','Use testng.xml parameters to define request specs','REST Assured request specs cannot be reused'],answer:0,explanation:'RequestSpecification reqSpec = new RequestSpecBuilder().setBaseUri(BASE_URL).addHeader("Authorization", token).build() in @BeforeClass creates a reusable spec. Each test calls RestAssured.given(reqSpec).when().get("/endpoint") without repeating common setup.'},
{id:2059,topic:'testng',difficulty:'intermediate',question:'What is the standard pattern for taking a screenshot on test failure in a TestNG + Selenium test suite?',options:['Add screenshot logic inside every @Test method','Implement ITestListener.onTestFailure() to capture a TakesScreenshot screenshot and save/attach it','Use @Test(screenshotOnFailure=true)','Configure screenshots in testng.xml'],answer:1,explanation:'ITestListener.onTestFailure(ITestResult result) receives failed test context. Cast the WebDriver to TakesScreenshot, call getScreenshotAs(OutputType.BYTES), then save to a file or attach to Allure/ExtentReports. This centralizes screenshot logic without cluttering test methods.'},
{id:2060,topic:'testng',difficulty:'intermediate',question:'In the screenshot-on-failure listener, how do you retrieve the current WebDriver instance for the failed test?',options:['From a static WebDriver field','From a ThreadLocal variable exposed via a static getter in the base test class','From the ITestResult object directly','From testng.xml parameters'],answer:1,explanation:'The base test class holds a ThreadLocal<WebDriver>. A static getter (DriverManager.getDriver()) returns the current thread\'s driver. The ITestListener calls this getter inside onTestFailure, ensuring it gets the correct driver for the thread that ran the failing test.'},
{id:2061,topic:'testng',difficulty:'intermediate',question:'What is the Base Test Class pattern in TestNG and why is it used?',options:['A class that contains all @Test methods','A parent class containing shared setup/teardown (@Before*/@After*), utility methods, and common configuration that all test classes inherit','A class that generates test data','A class that manages testng.xml parsing'],answer:1,explanation:'The Base Test Class (e.g., BaseTest) centralizes WebDriver initialization, ThreadLocal management, logging setup, and screenshot-on-failure logic. Test classes extend it and inherit this infrastructure, keeping individual test classes focused on test scenarios rather than plumbing.'},
{id:2062,topic:'testng',difficulty:'beginner',question:'What is the benefit of having a single @BeforeSuite method in a Base Test Class?',options:['It runs before every test method','It executes once for the entire suite, making it ideal for expensive one-time setup like starting a test server or loading global configuration','It replaces @BeforeClass in all subclasses','It ensures thread safety'],answer:1,explanation:'@BeforeSuite executes exactly once at the start of the entire suite, regardless of how many test classes are present. Expensive operations like spinning up a Docker container or loading a configuration database are done once and shared, rather than repeated per class.'},
{id:2063,topic:'testng',difficulty:'intermediate',question:'When implementing a Base Test Class pattern, what is the recommended way to expose the WebDriver to subclasses?',options:['Use a public static field','Use a protected method that returns the ThreadLocal driver for the current thread','Pass it via constructor injection','Use testng.xml parameters'],answer:1,explanation:'A protected getDriver() method returning ThreadLocal<WebDriver>.get() provides type-safe, thread-aware access to the current driver. Subclasses call getDriver() without knowing the ThreadLocal implementation, and the method naturally returns the correct instance during parallel runs.'},
{id:2064,topic:'testng',difficulty:'advanced',question:'In TestNG, how do you retry failed tests automatically using IRetryAnalyzer?',options:['Add retryCount attribute to @Test','Implement IRetryAnalyzer interface with retry() method and assign it via @Test(retryAnalyzer=MyRetry.class)','Configure retries in testng.xml','Use @Test(invocationCount=3, skipFailedInvocations=true)'],answer:1,explanation:'IRetryAnalyzer.retry(ITestResult result) returns true to re-run the test and false to accept the failure. Assigning it with @Test(retryAnalyzer=RetryAnalyzer.class) enables per-test retry logic, commonly used to handle network flakiness or transient CI environment issues.'},
{id:2065,topic:'testng',difficulty:'advanced',question:'What is the side effect of using IRetryAnalyzer where retried tests appear multiple times in TestNG reports?',options:['No side effect','Failed attempts are marked SKIP in the report while only the last result (pass or fail) is marked correctly, potentially inflating skip counts','All retry attempts are marked as passed','Retried tests are hidden from reports'],answer:1,explanation:'Each retry invocation is recorded: failed attempts appear as SKIP and only the final result is PASS or FAIL. Some reporting tools (Allure, ExtentReports) count these SKIPs, inflating numbers. Custom IReporter or result-filtering logic is needed to collapse retries into single results.'},
{id:2066,topic:'testng',difficulty:'intermediate',question:'Which @Test attribute controls the number of times a test is retried when using invocationCount (not IRetryAnalyzer)?',options:['retryCount','failedInvocationCount','skipFailedInvocations with invocationCount','successPercentage'],answer:2,explanation:'@Test(invocationCount=10, skipFailedInvocations=true) runs the method 10 times and skips (rather than fails) the entire test when invocations fail. Combined with successPercentage=80, it allows up to 20% failure across invocations before marking the test as failed.'},
{id:2067,topic:'testng',difficulty:'intermediate',question:'How do you pass a parameter from testng.xml to a @BeforeMethod in TestNG?',options:['Use @Parameters({"paramName"}) on the @BeforeMethod','Add paramName as a method argument without annotation','Declare it as a static field initialized from System.getProperty','Parameters can only be passed to @Test methods'],answer:0,explanation:'@Parameters works on any configuration method including @BeforeMethod, @BeforeClass, etc. The method argument types must match the parameter values (typically String). TestNG resolves the parameter name from testng.xml at runtime and injects the value.'},
{id:2068,topic:'testng',difficulty:'intermediate',question:'What does the @Factory annotation do in TestNG?',options:['Creates test data factories','Marks a method that returns an array of test class instances, allowing dynamic test creation with different constructor arguments','Generates testng.xml files dynamically','Creates mock objects'],answer:1,explanation:'@Factory on a method returning Object[] tells TestNG to instantiate multiple test class instances, each potentially configured differently (e.g., different browsers or URLs). This enables data-driven class instantiation without duplicating class definitions or testng.xml entries.'},
{id:2069,topic:'testng',difficulty:'advanced',question:'How does @Factory differ from @DataProvider in TestNG?',options:['No difference','@Factory creates multiple class instances (different constructor arguments); @DataProvider provides multiple data rows to a single @Test method','@DataProvider creates class instances; @Factory provides test data','@Factory is for integration tests; @DataProvider is for unit tests'],answer:1,explanation:'@DataProvider feeds data to one @Test method, running it N times within the same class instance. @Factory creates N separate class instances (with different constructor parameters), running all @Test methods of each instance — a more coarse-grained form of parameterization.'},
{id:2070,topic:'testng',difficulty:'intermediate',question:'In TestNG Maven Surefire configuration, how do you exclude a specific test class from execution?',options:['<exclude>**/MyTest.java</exclude>','<excludes><exclude>**/MyTest.class</exclude></excludes>','<excludeClasses><class>MyTest</class></excludeClasses>','Add enabled=false to all methods in the class'],answer:1,explanation:'Inside maven-surefire-plugin <configuration>, the <excludes> element accepts Ant-style patterns. <exclude>**/MyTest.class</exclude> (or **/*IT.java, etc.) prevents matching classes from being collected, providing build-level exclusion independent of test code.'},
{id:2071,topic:'testng',difficulty:'intermediate',question:'Which TestNG feature allows a group to include another group, simplifying group membership management?',options:['Group aliasing','Group inheritance via <define> in testng.xml','Meta-groups','Group chaining'],answer:1,explanation:'In testng.xml\'s <groups><define name="all"><include name="smoke"/><include name="regression"/></define></groups> creates a meta-group. Running group "all" includes all tests from both "smoke" and "regression", making it easy to compose group hierarchies without annotating every test.'},
{id:2072,topic:'testng',difficulty:'intermediate',question:'How do you run only smoke tests from a testng.xml suite that has multiple groups defined?',options:['Use -Dgroups=smoke on the command line','In testng.xml: <groups><run><include name="smoke"/></run></groups>','Both A and B are valid approaches','Add @Test(groups="smoke") to testng.xml'],answer:2,explanation:'Both approaches are valid. The testng.xml <groups><run><include name="smoke"/></run></groups> is a static configuration. The -groups "smoke" CLI flag or Maven -Dgroups=smoke achieves the same dynamically without editing the XML file, useful in CI pipelines.'},
{id:2073,topic:'testng',difficulty:'advanced',question:'What is the purpose of IMethodInterceptor in TestNG?',options:['To intercept HTTP calls made by tests','To modify the list of test methods to be run after collection but before execution, enabling custom ordering, filtering, or injection','To intercept TestNG XML parsing','To intercept assertions'],answer:1,explanation:'IMethodInterceptor.intercept(List<IMethodInstance> methods, ITestContext context) receives the full list of collected test methods and returns a (possibly modified) list. This enables programmatic reordering, dynamic filtering, or injecting additional methods at runtime — more powerful than static testng.xml configuration.'},
{id:2074,topic:'testng',difficulty:'intermediate',question:'Which TestNG class represents the result of a single test method invocation and is used in listener callbacks?',options:['ITestMethod','ITestResult','TestResult','ITestInvocationResult'],answer:1,explanation:'ITestResult encapsulates the outcome of a test method: status (SUCCESS, FAILURE, SKIP), the Throwable that caused failure, start/end times, parameters passed, and the test instance. Listeners receive ITestResult objects in callbacks like onTestFailure(ITestResult result).'},
{id:2075,topic:'testng',difficulty:'intermediate',question:'How do you register a TestNG listener globally in testng.xml (for all tests in the suite)?',options:['<listener class="com.example.MyListener"/> inside <listeners> at the suite level','@Listeners(MyListener.class) on every test class','Add listener to Maven Surefire <configuration>','Register in @BeforeSuite'],answer:0,explanation:'Adding <listeners><listener class-name="com.example.MyListener"/></listeners> inside the <suite> tag in testng.xml registers the listener globally. All tests in the suite use it. This is cleaner than annotating every class with @Listeners.'},
{id:2076,topic:'testng',difficulty:'advanced',question:'What is the Java ServiceLoader mechanism in TestNG listener registration?',options:['TestNG listeners registered in META-INF/services/org.testng.ITestNGListener are loaded automatically without testng.xml or @Listeners annotation','ServiceLoader is used for DataProviders','ServiceLoader manages thread pools for parallel tests','ServiceLoader is used to load testng.xml files'],answer:0,explanation:'Creating META-INF/services/org.testng.ITestNGListener with the fully qualified listener class name causes Java\'s ServiceLoader to auto-register the listener whenever TestNG runs, regardless of how it is launched. This is the most transparent integration approach for library authors.'},
{id:2077,topic:'testng',difficulty:'intermediate',question:'Which TestNG annotation marks a method as providing data and what must its return type be?',options:['@DataSupplier returning List<Object>','@DataProvider returning Object[][] or Iterator<Object[]>','@TestData returning Object[]','@Parameters returning Map<String,Object>'],answer:1,explanation:'@DataProvider methods must return Object[][] (each inner array is one invocation\'s arguments) or Iterator<Object[]> (for lazy/streaming data generation). The annotated @Test method\'s parameter types must match the array elements for TestNG to inject them correctly.'},
{id:2078,topic:'testng',difficulty:'advanced',question:'How can a @DataProvider method access the ITestContext or ITestNGMethod of the currently-requesting test?',options:['It cannot','Add ITestContext or ITestNGMethod as a parameter to the @DataProvider method; TestNG injects them automatically','Retrieve them from a static ThreadLocal','Use @Parameters on the DataProvider'],answer:1,explanation:'TestNG inspects the @DataProvider method\'s parameter types. If ITestContext or ITestNGMethod is present, TestNG injects the current suite context or the metadata of the requesting test method. This allows data to be customized based on which test is requesting it.'},
{id:2079,topic:'testng',difficulty:'intermediate',question:'What is the difference between Assert.assertEquals and Assert.assertSame in TestNG?',options:['No difference','assertEquals checks value equality (using .equals()); assertSame checks reference equality (==)','assertSame checks value equality; assertEquals checks reference equality','assertEquals is for primitives; assertSame is for objects'],answer:1,explanation:'Assert.assertEquals(actual, expected) uses the equals() method — two distinct objects with equal content pass. Assert.assertSame(actual, expected) checks that both references point to the exact same object instance using == identity comparison.'},
{id:2080,topic:'testng',difficulty:'advanced',question:'In a TestNG suite with thousands of tests, what is the best practice to prevent OutOfMemoryError caused by TestNG keeping all ITestResult objects in memory?',options:['Reduce test count','Implement IReporter to process results and clear them, or configure TestNG\'s result retention settings; avoid storing all ITestResult objects in listener fields','Use parallel execution to spread memory usage','Set -Xmx to maximum JVM heap'],answer:1,explanation:'TestNG stores results for reporting; listeners that also cache ITestResult objects in lists compound memory pressure. Best practice: process and log results immediately in onTestSuccess/onTestFailure callbacks rather than accumulating them, and configure generateReports=false if custom reporting is used.'}
]);
